mapper.update:
update OTH_STATUS_JOUR
set DURATION = (to_date(#{endTime,jdbcType=VARCHAR},'hh24:mi:ss')-to_date(beg_time,'hh24:mi:ss'))*3600*24 ,END_TIME = #{endTime,jdbcType=VARCHAR}
where ID = (select max(id) from OTH_STATUS_JOUR where user_id = #{userId,jdbcType=VARCHAR} and data_date = to_char(sysdate,'yyyy-mm-dd') and END_TIME IS NULL)

mapper.select:
select a.beg_time,a.end_Time,a.user_id,d.status_name as level1,c.status_name as level2,b.status_name as level3,a.memo,a.identity from (select * from OTH_STATUS_JOUR
order by ${orderByClause}
) a left join (select id,pid,status_name,sort from OTH_STATUS_TYPE where data_type = 'status' and level_grade=3) b on (a.status_id = b.id) left join (select id,pid,status_name,sort from OTH_STATUS_TYPE where data_type = 'status' and level_grade=2) c on (b.pid = c.id) left join (select id,pid,status_name,sort from OTH_STATUS_TYPE where data_type = 'status' and level_grade=1) d on (c.pid = d.id)
